function dmFriendlyLobby(){
  const panels=Array.from(dmLobby.querySelectorAll(':scope > section')),tabs=document.createElement('nav');tabs.setAttribute('aria-label','Разделы подготовки');tabs.style.cssText='display:flex;flex-wrap:wrap;gap:8px;margin:16px 0';
