function dmLobbyRender(){
  if(!dmLobby||!dmLobby.open||S.hero!==dmLobbyHero)return;
  const d=B.DUNGEONS.deadmines,rooms=d.rooms,optional=(d.optional||[]).filter(k=>B.ENCOUNTERS[k]);
  const active=document.activeElement,oldSlot=active?.dataset.dmSlot??(active?.hasAttribute('data-dm-add')?String(S.party.length-1):null);
  dmLobby.innerHTML='<div class="az-dm-layout"><header class="az-dm-head"><div class="az-dm-emblem" aria-hidden="true"></div><div><div class="az-eyebrow">ЗАПАДНЫЙ КРАЙ / ПОДЗЕМЕЛЬЕ</div><h2>Мёртвые копи</h2></div><button type="button" class="az-dm-close" aria-label="Закрыть">×</button></header><nav class="az-dm-nav" aria-label="Разделы подготовки"></nav><div class="az-dm-scroll"><section><div class="az-dm-meta"></div><div class="az-dm-sectionhead"><h3>Ваш отряд</h3><span class="az-chip az-dm-count"></span></div><div data-dm-party></div><p data-dm-roles></p></section><section><div class="az-dm-sectionhead"><h3>Маршрут</h3><span class="az-chip">'+rooms.length+' основных · '+optional.length+' необязательный</span></div><ol data-dm-bosses></ol></section><section><div class="az-dm-sectionhead"><h3>Возможная добыча</h3><span class="az-chip">Справочник</span></div><p class="az-dm-muted">Список по боссам. Предмет за победу зависит от класса и основной характеристики героя; после получения ищите его в сумке.</p><div data-dm-loot></div></section><section><h3>Правила забега</h3><dl class="az-dm-rules"><dt>Опыт</dt><dd>'+B.dungeonXp(S.level,'deadmines')+' за основные комнаты. Необязательный босс даёт опыт отдельно; награда за задание выдаётся один раз.</dd><dt>Восстановление</dt><dd>Здоровье и мана переносятся. После комнаты живые восстанавливают до '+Math.round(B.RECOVERY.hp*100)+'% максимума ХП и '+Math.round(B.RECOVERY.mana*100)+'% маны, не выше максимума. Павшие сами не встают. Отдых полностью восстанавливает отряд; доступно: '+d.rests+'. Смена вещей не лечит.</dd><dt>Выход</dt><dd>Можно выйти между боями с полученным. Перезагрузка сохраняет героя и добычу, но не продолжает забег.</dd></dl></section></div><footer class="az-dm-footer"></footer></div>';
  dmLobby.querySelector('header button').onclick=()=>dmLobby.close();
  const body=dmLobby.querySelector('.az-dm-scroll'),panels=Array.from(body.children),nav=dmLobby.querySelector('nav'),tabs=[];
  function select(i){dmLobby.dataset.dmTab=String(i);panels.forEach((p,n)=>{p.hidden=n!==i;});tabs.forEach((t,n)=>t.setAttribute('aria-pressed',String(n===i)));body.scrollTop=0;}
  ['Отряд','Боссы','Добыча','Правила'].forEach((label,i)=>{const b=gearButton(label,()=>select(i));b.setAttribute('aria-controls','az-dm-panel-'+i);panels[i].id='az-dm-panel-'+i;tabs.push(b);nav.append(b);});
  select(Math.min(3,Math.max(0,Number(dmLobby.dataset.dmTab)||0)));
  const level=hLevel('me'),below=level<d.level,over=S.party.length>d.size,allowed=dmLobbyAllowed();
  dmLobby.querySelector('.az-dm-meta').innerHTML='<div class="az-dm-stat '+(below?'az-warn':'')+'"><small>Уровень героя</small><strong>'+level+' <span>/ рекоменд. '+d.level+'</span></strong><small>'+(below?'Ниже рекомендации':'Уровень подходит')+'</small></div><div class="az-dm-stat"><small>Маршрут</small><strong>'+rooms.length+' <span>основных боёв</span></strong><small>'+optional.length+' по выбору</small></div><div class="az-dm-stat"><small>Запас отряда</small><strong>'+d.rests+' <span>полных отдыха</span></strong><small>Между боями</small></div>';
  dmLobby.querySelector('.az-dm-count').textContent=S.party.length+' / '+d.size+' занято';
  const party=dmLobby.querySelector('[data-dm-party]'),roles={tank:0,heal:0,dd:0};
  S.party.forEach((k,i)=>{const cls=clsOf(k),sp=B.specOf(cls,specKey(k));roles[sp.role]++;const b=i===0?document.createElement('div'):gearButton('',()=>{if(dmLobbyAllowed())azOpen(i,b);});b.className='az-dm-member';b.dataset.dmSlot=String(i);b.innerHTML='<span class="az-dm-portrait">'+classBadge(cls,specKey(k))+'</span><span><small>'+ (i===0?'Вы · лидер':'В отряде · заменить')+'</small><strong>'+esc(heroName(k)||B.CLASSES[cls].name)+'</strong><small>'+hLevel(k)+' ур. · '+esc(RN[sp.role])+'</small></span>';party.append(b);});
  for(let i=S.party.length;i<d.size;i++){const next=i===S.party.length,b=next?gearButton('',()=>{if(dmLobbyAllowed())azOpen(S.party.length,b);}):document.createElement('div');b.className='az-dm-member az-dm-empty';if(next)b.dataset.dmAdd='';b.innerHTML='<span class="az-dm-portrait" aria-hidden="true">'+(next?'+':'·')+'</span><span><strong>'+(next?'Добавить соратника':'Свободное место')+'</strong><small>Слот '+(i+1)+' из '+d.size+'</small></span>';party.append(b);}
  const roleRow=dmLobby.querySelector('[data-dm-roles]');roleRow.innerHTML='<span class="az-chip">Танк: '+roles.tank+'</span><span class="az-chip">Лекарь: '+roles.heal+'</span><span class="az-chip">Бойцы: '+roles.dd+'</span>';
  const route=dmLobby.querySelector('[data-dm-bosses]'),loot=dmLobby.querySelector('[data-dm-loot]');
  const order=rooms.slice();order.splice(Math.max(0,order.length-1),0,...optional);
  const stats=[['armorFlat','Броня'],['stamina','Выносливость'],['strength','Сила'],['agility','Ловкость'],['intellect','Интеллект']];
  const slotIcons={head:'M3 12v-2a9 9 0 0 1 18 0v2l-3 1v6l-6-3-6 3v-6z M6 11h12',chest:'M8 3 4 5 2 10l4 2v8h12v-8l4-2-2-5-4-2-4 3z',legs:'M6 3h12l2 18h-6l-2-9-2 9H4L6 3z M6 7h12',feet:'M6 3h9v9l5 3v5H4v-5l2-3z M4 17h16'};
  const cls=clsOf('me'),primary=B.primaryKey(cls,S.specs?.me||B.CLASSES[cls].def),catalogue=dmCatalogue();
  for(const k of order){
    const e=B.ENCOUNTERS[k],opt=optional.includes(k),first=k===rooms[0],li=document.createElement('li');li.dataset.stage=opt?'optional':first?'next':'later';
    li.innerHTML='<span class="az-dm-step" aria-hidden="true">'+(opt?'◇':String(rooms.indexOf(k)+1).padStart(2,'0'))+'</span><div><strong>'+esc(e.name)+'</strong><small>'+e.level+' ур. · '+(opt?'Необязательный перед финалом':first?'Первый бой':'Ожидает впереди')+'</small><small>'+esc(e.tip||e.text||'')+'</small></div>';route.append(li);
    const details=document.createElement('details');details.innerHTML='<summary>'+esc(e.name)+' <small>варианты предметов</small></summary>';
    for(const item of catalogue.filter(i=>i.bossSource===k)){
      const p=document.createElement('p');p.className='az-dm-item';
      const on=S.hero.items?.[item.id]&&S.hero.gear?.[item.slot]===item.id,owned=S.hero.items?.[item.id],eligible=item.allowedClasses.includes(cls),fits=eligible&&item.lootPrimary===primary;
      p.innerHTML='<span class="az-dm-item-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="'+slotIcons[item.slot]+'"/></svg></span><span><strong>'+esc(item.name)+'</strong><small>'+esc(item.label)+' · с '+item.requiredLevel+' ур. · '+esc(stats.filter(([key])=>item[key]).map(([key,label])=>label+' +'+item[key]).join(' · '))+'</small><small>'+esc(on?'Уже надето':owned?'Уже есть в сумке':fits?(level>=item.requiredLevel?'Подходит вашему герою':'Подходит, но нужен уровень '+item.requiredLevel):eligible?'Для другой основной характеристики':'Для другого класса')+'</small></span>';details.append(p);
    }
    loot.append(details);
  }
  const footer=dmLobby.querySelector('footer'),note=document.createElement('div');note.className='az-dm-ready';note.id='az-dm-readiness';note.innerHTML='<strong>'+(over?'Слишком большой отряд':!allowed?'Начало недоступно':below?'Можно начать · уровень ниже рекомендации':'Можно начать')+'</strong><small>'+(over?'Уберите лишних участников через занятый слот.':!allowed?'Дождитесь окончания текущего действия.':!roles.heal?'Лекаря нет. Далее: путь ко входу и первый бой.':'Далее: путь ко входу и первый бой.')+'</small>';footer.append(note);
  const start=gearButton('Начать забег',()=>{if(!dmLobbyAllowed()||S.hero!==dmLobbyHero||S.party.length>d.size)return;dmLobbyStarting=true;dmLobby.close();if(!enterFreeDeadmines()){dmLobbyStarting=false;dmOpenLobby();}});start.dataset.dmStart='';start.disabled=!allowed||over;start.setAttribute('aria-describedby',note.id);footer.append(start);
  if(oldSlot!==null){const slot=party.querySelector('button[data-dm-slot="'+oldSlot+'"]')||party.querySelector('button[data-dm-add]');if(slot&&!slot.closest('[hidden]'))slot.focus();}
}
